// 以无依赖 Worker 提供原有静态页面与匿名统计，不增加前端框架。
// 构建时把真实静态文件原样嵌入同一入口；页面仍可从 dist/index.html 本地打开。
const validEvents = new Set(['page_view','project_preview','project_interest','qr_view','experience_view','experience_cta','invitation_click','qr_expand','server_activity_click','server_guide_open','coupon_view','coupon_click','coupon_open']);
const validDetails = new Set(['','website','presentation','content','product','library','geo','omnichannel','skills','agent','workbuddy','fde','aliyun','tencent','yisu','ucloud','hero','mobile','content','sticky','footer']);
const validPlacements = new Set(['homepage','guide','experience']);
async function recordEvents(request, env) {
  if (request.method !== 'POST') return new Response(null,{status:405,headers:{Allow:'POST'}});
  const origin=request.headers.get('origin');
  if (origin && origin !== new URL(request.url).origin) return new Response(null,{status:403});
  if (!request.headers.get('content-type')?.startsWith('application/json')) return new Response(null,{status:415});
  if (Number(request.headers.get('content-length'))>8192) return new Response(null,{status:413});
  const raw=await request.text();
  if(raw.length>8192)return new Response(null,{status:413});
  let payload;try{payload=JSON.parse(raw);}catch{return new Response(null,{status:400});}
  if (!payload || !Array.isArray(payload.events) || payload.events.length<1 || payload.events.length>20 || !['mobile','desktop'].includes(payload.device) || typeof payload.version!=='string' || !/^[a-zA-Z0-9_-]{1,48}$/.test(payload.version)) return new Response(null,{status:400});
  const events=payload.events.filter(e=>e&&validEvents.has(e.name)&&validDetails.has(e.detail||'')&&validPlacements.has(e.placement||'homepage'));
  if(events.length!==payload.events.length)return new Response(null,{status:400});
  if(!env.DB)return new Response(null,{status:503});
  // 只保存按日汇总的动作次数，不保存 IP、二维码内容、微信账号或访问者标识。
  const day=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  const sql='INSERT INTO event_totals (day,event,detail,placement,device,version,count) VALUES (?,?,?,?,?,?,1) ON CONFLICT(day,event,detail,placement,device,version) DO UPDATE SET count=count+1';
  try{await env.DB.batch(events.map(e=>env.DB.prepare(sql).bind(day,e.name,e.detail||'',e.placement||'homepage',payload.device,payload.version)));return new Response(null,{status:204,headers:{'Cache-Control':'no-store'}});}catch{return new Response(null,{status:503});}
}
async function readMetrics(request, env) {
  // 正式统计接口只有设置私密 STATS_TOKEN 后才开启，口令从不写入网页源码。
  if(!env.STATS_TOKEN)return new Response(null,{status:404});
  if(request.headers.get('authorization')!==`Bearer ${env.STATS_TOKEN}`)return new Response(null,{status:401});
  if(!env.DB)return new Response(null,{status:503});
  const result=await env.DB.prepare('SELECT day,event,detail,placement,device,version,count FROM event_totals ORDER BY day DESC,event LIMIT 2000').all();
  return Response.json({rows:result.results},{headers:{'Cache-Control':'no-store'}});
}


const assets = {"/app.js":{"type":"text/javascript; charset=utf-8","data":""},"/assets/coupon-qr.png":{"type":"image/png","data":""},"/assets/invitation-qr.png":{"type":"image/png","data":""},"/assets/landing-mark.svg":{"type":"image/svg+xml","data":""},"/config.js":{"type":"text/javascript; charset=utf-8","data":""},"/index.html":{"type":"text/html; charset=utf-8","data":""},"/styles.css":{"type":"text/css; charset=utf-8","data":""}};
export default {
  async fetch(request, env) {
    const pathname=new URL(request.url).pathname;
    if(pathname==='/api/events')return recordEvents(request,env);
    if(pathname==='/api/metrics')return readMetrics(request,env);
    if(!['GET','HEAD'].includes(request.method))return new Response(null,{status:405});
    const file=assets[pathname==='/'?'/index.html':pathname];
    if(!file)return new Response('页面不存在',{status:404,headers:{'content-type':'text/plain; charset=utf-8'}});
    const headers={'content-type':file.type,'cache-control':file.type.startsWith('image/')?'public,max-age=86400':'no-cache','x-content-type-options':'nosniff'};
    const bytes=Uint8Array.from(atob(file.data),c=>c.charCodeAt(0));
    return new Response(request.method==='HEAD'?null:bytes,{headers});
  }
};

